const $=s=>document.querySelector(s);
const money=n=>'₹'+n.toLocaleString('en-IN');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readStore(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback}catch{return fallback}}
let saved=readStore('dormmart-saved',[]).filter(Number.isInteger), requests=readStore('dormmart-requests',[]).filter(x=>x&&Number.isInteger(x.itemId)&&typeof x.id==='string'), toastTimer;
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{toast('Browser storage is unavailable. Changes last for this visit.')}}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
const categories=[...new Set(LISTINGS.map(x=>x.category))];
$('#category').insertAdjacentHTML('beforeend',categories.map(x=>`<option>${x}</option>`).join(''));
$('#home-categories').innerHTML=['Everything',...categories].map(x=>`<button class="chip" data-category="${x==='Everything'?'all':x}">${x==='Everything'?'✳ ':''}${x}</button>`).join('');
function card(x){return `<article class="card"><div class="item-art" style="--item-color:${x.color}" aria-hidden="true"><span>${x.emoji}</span></div><span class="mode-badge">${x.mode==='share'?'FREE TO SHARE':x.mode==='rent'?'FOR RENT':'FOR SALE'}</span><button type="button" class="save" data-save="${x.id}" aria-label="Save ${escapeHTML(x.title)}" aria-pressed="${saved.includes(x.id)}">${saved.includes(x.id)?'♥':'♡'}</button><div class="card-body"><div class="card-meta"><span>${x.category}</span><span>◎ ${x.distance} km away</span></div><h3><a class="card-link" href="#item-${x.id}">${x.title}</a></h3><div class="card-price">${x.price?money(x.price):'Free'} <small>${x.mode==='rent'?'/ day':x.mode==='share'?'to borrow':'to keep'}</small></div><div class="seller"><span>${x.owner} ${x.verified?'<span class="verified">✓ Email verified</span>':''}</span><span>${x.reviews?'★ '+x.rating+' ('+x.reviews+')':'No reviews'}</span></div></div></article>`}
function filters(){return {query:$('#query').value,mode:$('#mode').value,category:$('#category').value,radius:Number($('#radius').value),price:$('#price').value,verified:$('#verified').checked,saved:$('#saved').checked,sort:$('#sort').value}}
function render(){const items=filterListings(LISTINGS,filters(),saved);$('#results').innerHTML=items.map(card).join('');$('#result-count').textContent=`${items.length} ${items.length===1?'find':'finds'} nearby`;$('#empty').hidden=items.length>0;$('#radius-value').value=$('#radius').value;$('#saved-count').textContent=saved.length;$('#featured').innerHTML=LISTINGS.slice(0,4).map(card).join('')}
$('#filters').addEventListener('input',render);$('#filters').addEventListener('submit',e=>e.preventDefault());$('#filters').addEventListener('reset',()=>setTimeout(render,0));
$('#hero-search').addEventListener('submit',e=>{e.preventDefault();$('#query').value=new FormData(e.target).get('query');location.hash='explore';render()});
$('#home-categories').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){$('#category').value=b.dataset.category;location.hash='explore';render()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(!b)return;const id=Number(b.dataset.save);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist('dormmart-saved',saved);render();document.querySelector(`${lastPage === 'explore' ? '#results' : '#featured'} [data-save="${id}"]`)?.focus();toast(saved.includes(id)?'Saved for later.':'Removed from saved items.')});
$('#saved-button').onclick=()=>{$('#saved').checked=true;location.hash='explore';render()};
let returnFocus=null,lastPage='home';
function showModal(html){if(!$('#modal').open)returnFocus=document.activeElement;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){ $('#modal').close();if(location.hash.startsWith('#item-')){history.replaceState(null,'','#'+lastPage)}returnFocus?.focus() }
$('.close').onclick=closeModal;$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function nextDate(){const d=new Date();d.setDate(d.getDate()+1);return localDate(d)}
function openItem(id){const x=LISTINGS.find(x=>x.id===id);if(!x)return;const rental=x.mode==='rent',borrow=x.mode!=='buy';showModal(`<p class="eyebrow">${x.category} · ${x.condition}</p><h2 id="modal-title">${x.title}</h2><div class="item-art detail-art" style="--item-color:${x.color}" aria-hidden="true"><span>${x.emoji}</span></div><p>${x.description}</p><p class="micro">${x.owner} · ${x.distance} km away · ${x.reviews?x.rating+' / 5 from '+x.reviews+' reviews':'No reviews yet'}<br>${x.verified?'✓ Email verified':'Email not verified'}${x.student?' · ✓ Student affiliation reviewed':''}<br>All trust signals and distances are illustrative demo data.</p><form class="detail-form" id="booking-form">${borrow?`<div class="detail-grid"><label>Pickup date<input required type="date" name="start" min="${localDate()}" value="${localDate()}"></label><label>Return date<input required type="date" name="end" min="${nextDate()}" value="${nextDate()}"></label></div>`:''}${rental?`<label>Security option<select name="security"><option value="deposit">Refundable deposit — ${money(x.deposit)}</option>${x.alternative?'<option value="guarantor">Request a guarantor instead — owner approval needed</option>':''}</select></label>`:''}<div class="quote" id="quote" aria-live="polite"></div><p class="notice">${rental?'Deposit return follows confirmed return and condition review. A guarantor is only a proposed alternative, subject to owner approval. ':''}Pickup at the campus main gate after agreement. No exact home address is shared. ${borrow?'Requests do not reserve dates.':'Purchase interest does not reserve the item.'}</p><label class="check"><input type="checkbox" required> I understand this is a demo request; no payment is collected.</label><button class="button" type="submit">${x.mode==='buy'?'Send purchase interest':'Request '+(rental?'rental':'to borrow')} ↗</button><p class="micro">${borrow?'1–'+(rental?'30':'7')+' days · minimum one full day · zero platform fees in this demo':'Owner confirmation is required before arranging pickup.'}</p></form>`);
 const form=$('#booking-form');function quote(){const data=new FormData(form);let days=borrow?(Date.parse(data.get('end'))-Date.parse(data.get('start')))/86400000:1;const valid=!borrow||(data.get('start')>=localDate()&&Number.isInteger(days)&&days>=1&&days<=(rental?30:7));if(borrow)form.elements.end.setCustomValidity(valid?'':'Choose a future pickup and a return 1–'+(rental?30:7)+' days later.');const security=data.get('security');const q=calculateQuote(x,days,security);$('#quote').innerHTML=valid?`${rental?`${days} day${days===1?'':'s'} × ${money(x.price)}`:x.mode==='buy'?'Item price':'Sharing fee'}<strong>${money(q.fee)}</strong><br>Refundable security<strong>${money(q.deposit)}</strong><hr>Estimated total<strong>${money(q.total)}</strong>${security==='guarantor'?'<p class="micro">Conditional estimate: deposit waived only if the owner accepts the guarantor.</p>':''}`:'Select valid dates to see your estimate.';return {valid,days,security,q,data}}
 form.addEventListener('input',quote);quote();form.onsubmit=e=>{e.preventDefault();const z=quote();if(!z.valid||!form.reportValidity())return;const request={id:'DM-'+Date.now().toString(36).toUpperCase(),itemId:x.id,start:z.data.get('start')||null,end:z.data.get('end')||null,security:z.security||'none',total:z.q.total,status:'Pending owner acceptance'};requests.unshift(request);persist('dormmart-requests',requests);showModal(`<p class="eyebrow">DEMO REQUEST SENT</p><h2 id="modal-title">Good things start here.</h2><p>Your request for <strong>${x.title}</strong> is pending owner acceptance.</p><div class="quote">Reference <strong>${request.id}</strong><br>Estimated total <strong>${money(z.q.total)}</strong></div><p class="notice">Nothing has been charged or reserved. This request is saved only in this browser. A real marketplace would notify the owner here.</p><button class="button" id="done">Keep exploring ↗</button>`);$('#done').onclick=closeModal}
}
$('#requests-button').onclick=()=>{showModal(`<p class="eyebrow">SAVED IN THIS BROWSER</p><h2 id="modal-title">Your demo requests</h2>${requests.length?requests.map(r=>{const x=LISTINGS.find(x=>x.id===r.itemId);return `<article class="request"><h3>${escapeHTML(x?.title||'Item unavailable')}</h3><p>${escapeHTML(r.id)} · ${escapeHTML(r.status)}<br>${r.start?escapeHTML(r.start)+' → '+escapeHTML(r.end)+'<br>':''}Estimated total: ${money(Number(r.total)||0)}</p>${r.status==='Pending owner acceptance'?`<button class="text-btn" data-cancel="${escapeHTML(r.id)}">Cancel request</button>`:''}</article>`}).join(''):'<p>No requests yet. Find something you love in Explore.</p>'}`)};
$('#modal-body').addEventListener('click',e=>{const b=e.target.closest('[data-cancel]');if(b){const r=requests.find(x=>x.id===b.dataset.cancel);if(r){r.status='Cancelled';persist('dormmart-requests',requests);$('#requests-button').click()}}});
$('#list-button').onclick=()=>{showModal('<p class="eyebrow">SELL · LEND · SHARE</p><h2 id="modal-title">Give your things a next chapter.</h2><p>Listing creation is the next screen in this prototype. For now, you can explore the sample catalogue and try a booking.</p><div class="notice">The planned flow collects photos, condition, price, approximate area, and rental security terms. Nothing is published from this demo.</div><p><a class="button" id="browse-instead" href="#explore">Browse sample listings ↗</a></p>');$('#browse-instead').onclick=closeModal};
function route(){const hash=location.hash||'#home';if(hash.startsWith('#item-')){openItem(Number(hash.slice(6)));return}if($('#modal').open)closeModal();const explore=hash==='#explore';lastPage=explore?'explore':'home';$('#home-view').hidden=explore;$('#explore-view').hidden=!explore;document.title=explore?'Explore nearby — DormMart':'DormMart — Good things, closer.';document.querySelectorAll('.header nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.hash===hash)a.setAttribute('aria-current','page')});if(hash==='#how')$('#how').scrollIntoView();else window.scrollTo(0,0)}
window.addEventListener('hashchange',route);render();route();


